async function hydrateImages() { for (const node of app.querySelectorAll('img[data-asset]')) { try { node.src = await protectedBlob(node.dataset.asset); } catch { node.alt = 'Protected lesson image unavailable'; } } }

function shuffle(items) { return [...items].sort(() => Math.random() - 0.5); }
function gameWords(course) { const all = (course.units || []).flatMap((u, unit) => (u.vocabulary || []).map((word) => ({ ...word, unit: unit + 1 }))).filter((w) => w.fr && (w.def_en || w.def_ar)); return shuffle([...new Map(all.map((w) => [String(w.fr).toLowerCase(), w])).values()]).slice(0, 24); }
function gameScorebar() { const g = state.game; return `<div class="game-scorebar"><span><strong>${g.score}</strong> points</span><span><strong>${g.streak}</strong> streak</span><span><strong>${Math.min(g.index + 1, g.words.length)}</strong> / ${g.words.length} cards</span></div>`; }
function gameModes() { return [['speed', 'Speed Choice', 'Choose the meaning fast.', '⚡'], ['match', 'Memory Match', 'Pair words and meanings.', '◈'], ['recall', 'Flash Recall', 'Retrieve before revealing.', '✦']].map(([mode, title, copy, icon]) => `<button class="game-mode ${state.game.mode === mode ? 'active' : ''}" data-game-mode="${mode}"><span>${icon}</span><strong>${title}</strong><small>${copy}</small></button>`).join(''); }
function speedRound() { const g = state.game; const word = g.words[g.index % g.words.length]; const answer = word.def_en || word.def_ar; const choices = shuffle([answer, ...shuffle(g.words.filter((w) => w !== word)).slice(0, 3).map((w) => w.def_en || w.def_ar)]); return `<article class="game-card"><p class="eyebrow">Speed choice</p><h2>What does <strong>${esc(word.fr)}</strong> mean?</h2><p class="game-context">${esc(word.ipa || word.pos || `Unit ${word.unit}`)}</p><div class="game-choices">${choices.map((choice) => `<button class="game-choice" data-game-answer="${esc(choice)}" ${g.answered ? 'disabled' : ''}>${esc(choice)}</button>`).join('')}</div>${g.answered ? `<p class="game-feedback ${g.lastCorrect ? 'ok' : 'no'}">${g.lastCorrect ? 'Correct — keep the chain alive.' : `The answer is “${esc(answer)}”.`}</p><button class="button" data-game-next>Next card →</button>` : '<p class="game-hint">Choose first. Correction comes immediately.</p>'}</article>`; }
function recallRound() { const g = state.game; const word = g.words[g.index % g.words.length]; return `<article class="game-card recall-game-card"><p class="eyebrow">Flash recall</p><div class="game-flash"><span class="flash-word">${esc(word.fr)}</span><span class="flash-meaning" ${g.revealed ? '' : 'hidden'}>${esc(word.def_en || word.def_ar)}</span></div>${g.revealed ? '<p class="game-feedback">Did you retrieve it before the reveal?</p><div class="buttons"><button class="button" data-game-rate="known">I knew it +10</button><button class="button alt" data-game-rate="review">Review it</button></div>' : '<button class="button" data-game-reveal>Reveal meaning</button>'}<p class="game-hint">Say the word aloud, then reveal the meaning.</p></article>`; }
function matchRound() { const g = state.game; const pairs = g.match.pairs || []; const left = pairs.map((w, i) => `<button class="match-tile ${g.match.matched.includes(i) ? 'matched' : ''}" data-match-side="left" data-match-index="${i}" ${g.match.matched.includes(i) ? 'disabled' : ''}>${esc(w.fr)}</button>`).join(''); const right = shuffle(pairs.map((w, i) => ({ ...w, i }))).map((w) => `<button class="match-tile ${g.match.matched.includes(w.i) ? 'matched' : ''}" data-match-side="right" data-match-index="${w.i}" ${g.match.matched.includes(w.i) ? 'disabled' : ''}>${esc(w.def_en || w.def_ar)}</button>`).join(''); return `<article class="game-card"><p class="eyebrow">Memory match</p><h2>Pair French with its meaning.</h2><div class="match-board"><div>${left}</div><div>${right}</div></div><p class="game-hint">Choose one tile on each side. Correct pairs stay lit.</p>${g.match.matched.length === pairs.length ? '<button class="button" data-game-new-round>Play another round →</button>' : ''}</article>`; }
function gameRound() { return state.game.mode === 'match' ? matchRound() : state.game.mode === 'recall' ? recallRound() : speedRound(); }
async function renderGames(level = state.game.level || 'A1') { if (state.session?.access_token) { try { await getMe(); } catch { saveSession(null); state.me = null; loadProgress(); } } if (!isActive()) { app.innerHTML = page('games', lockPanel('Gamified vocabulary games are available with an active membership.')); return; } const safe = LEVELS.includes(String(level).toUpperCase()) ? String(level).toUpperCase() : 'A1'; app.innerHTML = page('games', '<section class="loading-panel"><span class="loading-spinner"></span><p class="eyebrow">Vocabulary games</p><h1>Loading your word deck…</h1><p class="lead">Protected course vocabulary is being prepared.</p></section>'); try { const words = gameWords(await loadCourse(safe)); if (words.length < 4) throw new Error('This level does not have enough vocabulary for a game round yet.'); const changed = state.game.level !== safe || !state.game.words.length; state.game.level = safe; if (changed) { state.game.words = words; state.game.index = 0; state.game.score = 0; state.game.streak = 0; state.game.answered = false; state.game.revealed = false; } if (state.game.mode === 'match' && (!state.game.match.pairs || changed)) state.game.match = { pairs: shuffle(state.game.words).slice(0, 5), matched: [], selected: [] }; app.innerHTML = page('games', `<section class="games-hero"><div><p class="eyebrow">Gamified vocabulary games</p><h1>Make the words stick.</h1><p class="lead">Short rounds turn course vocabulary into retrieval: choose, pair, recall, repeat.</p></div><div class="game-level-picker"><span>Word deck</span><div>${LEVELS.map((item) => `<button class="${item === safe ? 'active' : ''}" data-game-level="${item}">${item}</button>`).join('')}</div></div></section><section class="game-studio"><div class="game-modes">${gameModes()}</div>${gameScorebar()}${gameRound()}</section><section class="game-principles"><article><strong>Retrieve</strong><span>Try before you reveal.</span></article><article><strong>Repeat</strong><span>Short rounds beat cramming.</span></article><article><strong>Use</strong><span>Return to the lesson when a word needs context.</span></article></section>`); } catch (error) { app.innerHTML = page('games', `<section class="error-state"><h1>Games unavailable</h1><p>${esc(error.message || 'Please retry in a moment.')}</p><button class="button" data-go="games">Retry</button></section>`); } }

